#include "s61_binary_deeper_cubic_field_20261101.hpp"
#include <chrono>
using namespace cubic_field;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&a):Poly(){fmpq_mpoly_set(p,a.p,ctx);}Poly(Poly&&a):Poly(){fmpq_mpoly_swap(p,a.p,ctx);}Poly&operator=(Poly a){fmpq_mpoly_swap(p,a.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
void write(ostream&o,const Poly&a){fmpq_t q;fmpq_init(q);ulong ex[2];int n=fmpq_mpoly_length(a.p,ctx);o<<n;for(int i=0;i<n;i++){fmpq_mpoly_get_term_coeff_fmpq(q,a.p,i,ctx);fmpq_mpoly_get_term_exp_ui(ex,a.p,i,ctx);char*s=fmpq_get_str(nullptr,10,q);o<<' '<<s<<' '<<ex[0]<<' '<<ex[1];flint_free(s);}o<<'\n';fmpq_clear(q);}
using Mat=vector<vector<Poly>>;
Mat readmat(istream&in,int nr,int nc){int n,m;in>>n>>m;assert(n==nr&&m==nc);Mat A(n,vector<Poly>(m));for(auto&r:A)for(auto&p:r)read_poly(in,p.p);return A;}
int main(int argc,char**argv){assert(argc==6);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]),bin(argv[2]),gin(argv[3]),old(argv[4]);ofstream out(argv[5]);assert(in&&bin&&gin&&old&&out);Poly D1,D2,DQ,D11Q,D12,D2Q;read_poly(in,D1.p);read_poly(in,D2.p);read_poly(in,DQ.p);fmpq_mpoly_mul(D11Q.p,D1.p,D1.p,ctx);fmpq_mpoly_mul(D11Q.p,D11Q.p,DQ.p,ctx);fmpq_mpoly_mul(D12.p,D1.p,D2.p,ctx);fmpq_mpoly_mul(D2Q.p,D2.p,DQ.p,ctx);vector<int>qp(132),rr(31);for(int&i:qp)in>>i;vector<map<int,string>>B(238);for(auto&r:B){int n;in>>n;for(int k=0;k<n;k++){int j;string c;in>>j>>c;r[j]=c;}}Mat A1=readmat(in,189,238),A2=readmat(in,189,106),T=readmat(in,132,106);int n,m,r,k;old>>n>>m>>r>>k;assert(n==147&&m==106&&r==31&&k==75);for(int&i:rr)old>>i;Mat S(31,vector<Poly>(106));fmpq_t coef;fmpq_init(coef);Poly tmp;for(int i=0;i<31;i++)for(int j=0;j<238;j++)if(!fmpq_mpoly_is_zero(A1[rr[i]+42][j].p,ctx))for(auto&[h,c]:B[j]){assert(fmpq_set_str(coef,c.c_str(),10)==0);fmpq_canonicalise(coef);fmpq_mpoly_scalar_mul_fmpq(tmp.p,A1[rr[i]+42][j].p,coef,ctx);fmpq_mpoly_add(S[i][h].p,S[i][h].p,tmp.p,ctx);}bin>>n>>m>>r;assert(n==117&&m==238&&r==106);out<<117<<' '<<106<<'\n';auto start=chrono::steady_clock::now();long total=0;for(int i=0;i<117;i++){vector<Poly>first(238),second(106),gamma(31),eff(106);for(auto&p:first)read_poly(bin,p.p);for(auto&p:second)read_poly(bin,p.p);string ss;gin>>ss>>k;assert(ss=="KERNEL"&&k==i);Poly gd;read_poly(gin,gd.p);for(auto&p:gamma)read_poly(gin,p.p);for(int j=0;j<117;j++){read_poly(gin,tmp.p);assert(j==i?fmpq_mpoly_equal(tmp.p,gd.p,ctx):fmpq_mpoly_is_zero(tmp.p,ctx));}Poly z,u,g,q,scale;for(int j=0;j<106;j++){fmpq_mpoly_mul(eff[j].p,second[j].p,D11Q.p,ctx);fmpq_mpoly_mul(eff[j].p,eff[j].p,gd.p,ctx);fmpq_mpoly_zero(z.p,ctx);for(int h=0;h<132;h++)if(!fmpq_mpoly_is_zero(first[qp[h]].p,ctx)&&!fmpq_mpoly_is_zero(T[h][j].p,ctx)){fmpq_mpoly_mul(tmp.p,first[qp[h]].p,T[h][j].p,ctx);fmpq_mpoly_add(z.p,z.p,tmp.p,ctx);}fmpq_mpoly_mul(tmp.p,z.p,D12.p,ctx);fmpq_mpoly_mul(tmp.p,tmp.p,gd.p,ctx);fmpq_mpoly_sub(eff[j].p,eff[j].p,tmp.p,ctx);fmpq_mpoly_zero(z.p,ctx);for(int h=0;h<31;h++)if(!fmpq_mpoly_is_zero(gamma[h].p,ctx)&&!fmpq_mpoly_is_zero(S[h][j].p,ctx)){fmpq_mpoly_mul(tmp.p,gamma[h].p,S[h][j].p,ctx);fmpq_mpoly_add(z.p,z.p,tmp.p,ctx);}fmpq_mpoly_mul(tmp.p,z.p,D2Q.p,ctx);fmpq_mpoly_add(eff[j].p,eff[j].p,tmp.p,ctx);}for(auto&p:eff){assert(fmpq_mpoly_gcd(q.p,g.p,p.p,ctx));g=q;}write(out,g);long nt=0;for(auto&p:eff){if(!fmpq_mpoly_is_zero(g.p,ctx)){assert(fmpq_mpoly_divides(q.p,p.p,g.p,ctx));p=q;}write(out,p);nt+=fmpq_mpoly_length(p.p,ctx);}out.flush();total+=nt;double sec=chrono::duration<double>(chrono::steady_clock::now()-start).count();if(i%5==0)cerr<<"EFFECTIVE "<<i<<" TERMS "<<nt<<" TOTAL "<<total<<" SEC "<<sec<<'\n';assert(total<5000000);}fmpq_clear(coef);cerr<<"PASS TERMS "<<total<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
